import {drawWorld,doorSlots,destinations} from './pixel-world.js';
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];const ctx=q('#world').getContext('2d');const motion=matchMedia('(prefers-reduced-motion: reduce)');
const info={tone:{title:'Tone Tower',kicker:'THE WAY UP',description:'Every sound opens a door. Climb the tower, one floor at a time.',entry:'Enter Tone Tower →'},rail:{title:'Skyrail',kicker:'NEXT STOP: THE HORIZON',description:'A little railcar. A very long way to go. Spell the sound to build the next bridge span.',entry:'Board Skyrail →'},practice:{title:'Practice Workshop',kicker:'A LITTLE TIME AT THE WORKBENCH',description:'Take your time with the sounds. No lives, no timer. Just you, the cat, and a little practice.',entry:'Visit the workshop →'}};
let scene='hub',destination='tone',progress=24,lives=4,count=2,practice=false,paused=false,review=false,result='',chosen=-1,actor={...destinations.tone},waypoints=[],walking=false,time=0,lastFrame=0,travel=0,build=0,remaining=25,deadline=0,clock=null,clockWasRunning=false,pendingClock=false,audioEpoch=0,guideWasPaused=false;
const audio=new Audio('../audio/fu2.mp3');audio.preload='auto';
function status(text,kind='neutral'){q('#status').textContent=text;q('#status').dataset.kind=kind}
function drawLives(event){if(scene==='hub'||scene==='practice'){q('#hud-right').innerHTML='<span class="world-weather">☁ A good day to explore</span>';return}q('#hud-right').innerHTML=practice?'<span class="world-weather">Untimed practice</span>':'<span class="hearts" role="img" aria-label="'+lives+' of 5 lives remaining">'+Array.from({length:5},(_,i)=>'<svg class="heart '+(i>=lives?'empty ':'')+(event==='lost'&&i===lives?'lost':event==='restored'&&i===lives-1?'restored':'')+'" viewBox="0 0 20 22" aria-hidden="true"><path d="M1 5L5 1h4l1 3 1-3h4l4 4v7L10 21 1 12Z"/></svg>').join('')+'</span>'}
function drawHud(){q('#hud-left').innerHTML=scene==='hub'?'THE HIGHLINE ISLES <span>Three places. One adventure.</span>':scene==='practice'?'PRACTICE WORKSHOP <span>A little practice goes a long way.</span>':scene==='tone'?'FLOOR '+progress+' / 100 <span>'+['The Atrium','Echo Halls','Lantern Workshop','Sky Gardens','The Beacon'][Math.min(4,Math.floor(progress/20))]+'</span>':'SPAN '+progress+' / 100 <span>'+['Cliffside Station','The Hanging Gardens','Copper Viaduct','Cloudline Pass','The Last Platform'][Math.min(4,Math.floor(progress/20))]+'</span>';q('#progress').value=progress;q('#progress-value').textContent=progress+' / 100';drawLives();q('#stage-badge').hidden=scene!=='rail';if(scene==='rail')q('#stage-badge').innerHTML=Math.ceil(remaining)+'s<small>TO THE NEXT GAP</small>'}
function stopClock(){clearInterval(clock);clock=null}
function resetClock(){stopClock();remaining=25;pendingClock=false;drawHud()}
function startClock(){if(scene!=='rail'||practice||paused||review)return;pendingClock=false;stopClock();deadline=performance.now()+remaining*1000;clock=setInterval(tick,50)}
function tick(){remaining=Math.max(0,(deadline-performance.now())/1000);q('#stage-badge').innerHTML=Math.ceil(remaining)+'s<small>TO THE NEXT GAP</small>';if(remaining<=0)timeout()}
function stopAudio(){audioEpoch++;pendingClock=false;audio.pause();audio.currentTime=0}
function replay(){if(paused)return;audio.pause();audio.currentTime=0;const epoch=++audioEpoch;audio.play().catch(()=>{if(epoch!==audioEpoch)return;pendingClock=false;stopClock();status('The recording could not play. Replay to try again.','error')})}
audio.addEventListener('ended',()=>{if(pendingClock&&scene==='rail'&&!paused&&!review)startClock()});
function setDoors(){const choices=[2,5,1,3,4,6].slice(0,count),slots=doorSlots(count);q('#door-targets').innerHTML=choices.map((tone,i)=>{const [x,y,w,h]=slots[i],keys=count===2?['←','→']:count===3?['←','↑ ↓','→']:count===4?['↑','←','→','↓']:choices.map(String);return '<button class="tone-choice" data-tone="'+tone+'" data-index="'+i+'" style="left:'+x/4.8+'%;top:'+y/2.88+'%;width:'+w/4.8+'%;height:'+h/2.88+'%" aria-label="Choose tone '+tone+'"><strong>'+tone+'</strong><kbd>'+keys[i]+'</kbd></button>'}).join('');qa('[data-tone]').forEach(b=>b.onclick=()=>{if(paused||review)return;chosen=Number(b.dataset.index);Number(b.dataset.tone)===2?correct():damage()})}
function selectDestination(value){if(scene!=='hub')showMap();destination=value;const d=info[value];q('#destination-kicker').textContent=d.kicker;q('#destination-title').textContent=d.title;q('#destination-description').textContent=d.description;q('#enter').textContent=d.entry;qa('[data-destination]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.destination===value));if(motion.matches){actor={...destinations[value]};arrive();return}const target=destinations[value];if(Math.hypot(actor.x-target.x,actor.y-target.y)<2){arrive();return}waypoints=[{x:237,y:206},{...target}];walking=true;q('#enter').disabled=true;status('Walking to '+d.title+'…')}
function arrive(){walking=false;waypoints=[];q('#enter').disabled=false;status(destination==='rail'?'The bell is ringing. Your railcar is ready.':destination==='practice'?'The kettle is on. Come in and practise.':'The tower is waiting. Ready to climb?')}
function showMap(){stopClock();stopAudio();scene='hub';practice=false;review=false;result='';paused=false;travel=0;build=0;setPauseUI();q('body').classList.remove('game-mode');q('#heading').textContent='Where shall we go?';q('#kicker').textContent='A LITTLE WORLD OF SOUND';q('#map-targets').hidden=false;q('#door-targets').hidden=true;q('#destination-copy').hidden=false;q('#entry-controls').hidden=false;q('#word').hidden=true;q('#typing-form').hidden=true;q('#instruction').hidden=true;q('#workshop-panel').hidden=true;q('#continue').hidden=true;q('#enter').disabled=walking;drawHud();selectCopy();q('#world').setAttribute('aria-label','A pixel world with a tower, cliffside railway station and practice workshop')}
function selectCopy(){const d=info[destination];q('#destination-kicker').textContent=d.kicker;q('#destination-title').textContent=d.title;q('#destination-description').textContent=d.description;q('#enter').textContent=d.entry;qa('[data-destination]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.destination===destination));status('Choose a place. Your little explorer will walk there.')}
function enter(value=destination,isPractice=false){if(walking)return;stopAudio();resetClock();scene=value;practice=isPractice;if(lives===0)lives=4;review=false;result='';chosen=-1;build=0;travel=0;paused=false;setPauseUI();q('#heading').textContent=info[value].title;q('#kicker').textContent=info[value].kicker;q('#map-targets').hidden=true;q('#destination-copy').hidden=value!=='practice';q('#entry-controls').hidden=true;q('#word').hidden=value==='practice';q('#typing-form').hidden=value!=='rail';q('#instruction').hidden=value!=='tone';q('#workshop-panel').hidden=value!=='practice';q('#door-targets').hidden=value!=='tone';q('body').classList.toggle('game-mode',value!=='practice');q('#continue').hidden=true;if(value==='practice'){q('#destination-kicker').textContent='WELCOME TO THE WORKSHOP';q('#destination-title').textContent='Make yourself at home.';q('#destination-description').textContent=info.practice.description;status('Choose a listening or spelling sample below.');drawHud();return}setDoors();next(false);if(value==='rail'&&!practice){pendingClock=true;replay()}q('#world').setAttribute('aria-label',value==='tone'?'A tall pixel tower with lit windows and doors at the base':'A brass and teal railcar waiting beside an unfinished cliffside viaduct')}
function next(play=true){stopAudio();resetClock();review=false;result='';chosen=-1;build=0;q('#continue').hidden=true;q('#spelling').textContent=scene==='tone'?'fu':'—';q('#answer').value='';q('#answer').disabled=false;q('#typing-form button').disabled=false;qa('[data-tone]').forEach(b=>{b.disabled=false;b.classList.remove('is-right','is-wrong')});status(scene==='tone'?'Listen, then choose the tone that opens the door.':practice?'Spell the sample at your own pace.':'Spell the sound to repair the bridge. Wrong spelling is free.');if(scene==='rail'){if(play&&!practice){pendingClock=true;replay()}q('#answer').focus({preventScroll:true})}drawHud()}
function settle(text,kind){stopClock();stopAudio();review=true;q('#spelling').textContent='fu2';q('#continue').hidden=false;q('#continue').textContent=lives===0&&!practice?'Back to the map →':'Continue →';qa('[data-tone]').forEach(b=>b.disabled=true);q('#answer').disabled=true;q('#typing-form button').disabled=true;status(text,kind);drawHud();q('#continue').focus({preventScroll:true})}
function correct(){if(paused||!['tone','rail'].includes(scene)||review)return;result='success';progress=Math.min(100,progress+1);if(scene==='rail'){build=0;travel=1.8}settle(progress===100?'✓ Journey complete. You made it.':scene==='rail'?'✓ Span repaired. Next stop, a little further.':'✓ Correct. Another floor lights up.','success');qa('[data-tone]').find(b=>b.dataset.tone==='2')?.classList.add('is-right')}
function damage(){if(paused||!['tone','rail'].includes(scene)||review)return;result='wrong';if(!practice)lives=Math.max(0,lives-1);settle(practice?'Not quite. Listen to fu2 and try again.':'✕ Not quite — 1 life lost. The answer is fu2.','error');drawLives('lost');qa('[data-tone]').forEach(b=>{if(b.dataset.tone==='2')b.classList.add('is-right');else if(Number(b.dataset.index)===chosen)b.classList.add('is-wrong')})}
function timeout(){if(scene!=='rail'||paused||review)return;result='wrong';travel=0;remaining=0;if(!practice)lives=Math.max(0,lives-1);settle(practice?'The railcar has stopped. Take your time.':'✕ Brakes on — 1 life lost. The bridge is still waiting.','error');drawLives('lost')}
function setPauseUI(){q('.play-frame').classList.toggle('paused',paused);q('#pause').setAttribute('aria-pressed',String(paused));q('#pause').setAttribute('aria-label',paused?'Resume scene':'Pause scene');q('#pause').textContent=paused?'▶':'Ⅱ'}
function togglePause(){paused=!paused;if(paused){clockWasRunning=Boolean(clock);if(clock){remaining=Math.max(0,(deadline-performance.now())/1000);stopClock()}audio.pause()}else if(clockWasRunning){startClock();clockWasRunning=false}setPauseUI()}
function frame(now){const dt=lastFrame?Math.min(.05,(now-lastFrame)/1000):0;lastFrame=now;if(!paused){if(!motion.matches)time+=dt;travel=Math.max(0,travel-dt);if(scene==='rail'&&result==='success')build=Math.min(1,build+(motion.matches?1:dt*2.5));if(walking){if(motion.matches){actor={...destinations[destination]};arrive()}else{const target=waypoints[0],dx=target.x-actor.x,dy=target.y-actor.y,dist=Math.hypot(dx,dy),step=88*dt;if(dist<=step){actor={...target};waypoints.shift();if(!waypoints.length)arrive()}else{actor.x+=dx/dist*step;actor.y+=dy/dist*step}}}}drawWorld(ctx,{scene,progress,count,time,travel,build,result,chosen,remaining,actor,walking,reduced:motion.matches});requestAnimationFrame(frame)}
qa('[data-destination]').forEach(b=>b.onclick=()=>selectDestination(b.dataset.destination));q('#enter').onclick=()=>enter();q('#map-button').onclick=showMap;q('#brand').onclick=e=>{e.preventDefault();showMap()};q('#pause').onclick=togglePause;q('#replay').onclick=replay;q('#continue').onclick=()=>lives===0&&!practice?showMap():next();q('#typing-form').onsubmit=e=>{e.preventDefault();if(paused||review)return;const value=q('#answer').value.toLowerCase().trim();if(value==='fu2'||value==='fu')correct();else{status('Not quite — adjust your spelling. No life lost.','retry');q('#answer').focus()}};q('#answer').oninput=()=>{if(!review)status('Keep listening. Wrong spelling does not cost a life.')};q('#practice-tone').onclick=()=>enter('tone',true);q('#practice-rail').onclick=()=>enter('rail',true);q('#progress').oninput=e=>{progress=Number(e.target.value);drawHud()};qa('[data-progress]').forEach(b=>b.onclick=()=>{progress=Number(b.dataset.progress);drawHud()});q('#door-count').onchange=e=>{count=Number(e.target.value);if(scene==='tone')setDoors()};q('#correct').onclick=correct;q('#damage').onclick=damage;q('#recover').onclick=()=>{if(paused||practice)return;lives=Math.min(5,lives+1);drawLives('restored');status('✦ One life restored.','success')};q('#run-timer').onclick=()=>{if(scene==='rail'){next(false);startClock()}};q('#timeout').onclick=timeout;q('#guide-button').onclick=()=>{guideWasPaused=paused;if(!paused)togglePause();q('#guide').showModal()};q('#close-guide').onclick=()=>q('#guide').close();q('#guide').addEventListener('close',()=>{audio.pause();if(paused&&!guideWasPaused)togglePause()});q('#guide-sample').onclick=()=>{audio.currentTime=0;audio.play().catch(()=>{})};document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused)togglePause()});document.addEventListener('keydown',e=>{if(e.isComposing||e.repeat||e.ctrlKey||e.metaKey||e.altKey||q('#guide').open)return;if(e.key.toLowerCase()==='r'){e.preventDefault();replay();return}if(e.key==='Escape'){e.preventDefault();togglePause();return}if(e.target.matches('input,select'))return;if(e.key==='Enter'&&review){e.preventDefault();q('#continue').click();return}if(scene==='tone'&&!paused&&!review){const index=count===2?({ArrowLeft:0,ArrowRight:1})[e.key]:count===3?({ArrowLeft:0,ArrowUp:1,ArrowDown:1,ArrowRight:2})[e.key]:count===4?({ArrowUp:0,ArrowLeft:1,ArrowRight:2,ArrowDown:3})[e.key]:undefined;const button=index!==undefined?qa('[data-tone]')[index]:qa('[data-tone]').find(b=>b.dataset.tone===e.key);if(button){e.preventDefault();button.click()}}});showMap();setDoors();requestAnimationFrame(frame);document.body.dataset.ready='true';
